   103	
   104	int
   105	get_idna_map (uint32_t c, IDNAMap * map)
   106	{
   107	  uint8_t *p;
   108	
   109	  if (c <= 0xFF)
   110	    p =
   111	      (uint8_t *)bsearch (&c, idna_map_8, sizeof (idna_map_8) / 5, 5,
   112	               (int (*)(const void *, const void *)) _compare_idna_map);
   113	  else if (c <= 0xFFFF)
   114	    p =
   115	      (uint8_t *)bsearch (&c, idna_map_16, sizeof (idna_map_16) / 7, 7,
   116	               (int (*)(const void *, const void *)) _compare_idna_map);
   117	  else if (c <= 0xFFFFFF)
   118	    p =
   119	      (uint8_t *)bsearch (&c, idna_map_24, sizeof (idna_map_24) / 8, 8,
   120	               (int (*)(const void *, const void *)) _compare_idna_map);
   121	  else
   122	    p = NULL;
   123	
   124	  if (!p)
   125	    {
   126	      memset (map, 0, sizeof (IDNAMap));
   127	      return -1;
   128	    }
   129	
   130	  _fill_map (c, p, map);
   131	  return 0;
   132	}
