   151	get_nfcqc_map (uint32_t c)
   152	{
   153	  return (NFCQCMap *)bsearch (&c, nfcqc_map, countof (nfcqc_map), sizeof (NFCQCMap),
   154	                  (int (*)(const void *, const void *)) _compare_nfcqc_map);
   155	}
