   157	/* copy 'n' codepoints from mapdata stream */
   158	int
   159	get_map_data (uint32_t * dst, const IDNAMap * map)
   160	{
   161	  int n = map->nmappings;
   162	  const uint8_t *src = mapdata + map->offset;
   163	
   164	  for (; n > 0; n--)
   165	    {
   166	      uint32_t cp = 0;
   167	      do
   168	        cp = (cp << 7) | (*src & 0x7F);
   169	      while (*src++ & 0x80);
   170	      *dst++ = cp;
   171	    }
   172	
   173	  return map->nmappings;
   174	}
